function ad_service_group_by_staff($rows){$grouped=[];foreach($rows as $row){$id=(int)($row['staff_id']??0);if($id>0)$grouped[$id][]=$row;}return $grouped;}
function ad_service_staff_summary($staff){$name=trim(implode(' ',array_filter([$staff['staff_name']??'',$staff['surname']??''])));if($name==='')$name=(string)($staff['alias']??'Unnamed staff');return ['staff_id'=>(int)($staff['staff_id']??0),'name'=>$name,'alias'=>(string)($staff['alias']??''),'phone'=>(string)($staff['staff_phone']??''),'email'=>(string)($staff['staff_email']??''),'location'=>(string)($staff['staff_residence']??''),'work_status'=>(string)($staff['work_status']??''),'user_status'=>(int)($staff['staff_user_status']??0)];}
function ad_service_attach_related($staff_rows){$ids=array_map(function($row){return (int)$row['staff_id'];},$staff_rows);$related=['next_of_kin'=>ad_service_group_by_staff(ad_repo_related('kp_staff_nok',$ids,'staff_id ASC')),'employment'=>ad_service_group_by_staff(ad_repo_related('kp_staff_employment',$ids,'staff_id ASC, employment_id DESC')),'employment_history'=>ad_service_group_by_staff(ad_repo_related('kp_staff_employment_history',$ids,'staff_id ASC, history_id DESC')),'profile_checks'=>ad_service_group_by_staff(ad_repo_related('kp_staff_profile_checks',$ids,'staff_id ASC')),'documents'=>ad_service_group_by_staff(ad_repo_related('kp_staff_documents',$ids,'staff_id ASC, document_id DESC'))];$records=[];foreach($staff_rows as $staff){$id=(int)$staff['staff_id'];$records[]=['staff'=>$staff,'summary'=>ad_service_staff_summary($staff),'next_of_kin'=>$related['next_of_kin'][$id]??[],'employment'=>$related['employment'][$id]??[],'employment_history'=>$related['employment_history'][$id]??[],'profile_checks'=>$related['profile_checks'][$id]??[],'documents'=>$related['documents'][$id]??[]];}return $records;}
function ad_service_staff_list($request){$search=ad_clean_text($request['search']??'');$page=max(1,ad_clean_int($request['page']??1,1));$limit=max(1,min(200,ad_clean_int($request['limit']??50,50)));$filters=['search'=>$search,'include_deleted'=>ad_clean_int($request['include_deleted']??0)===1,'limit'=>$limit,'offset'=>($page-1)*$limit];$result=ad_repo_staff_list($filters);if(!$result['ok'])return $result;$total=ad_repo_staff_count($filters);return ['ok'=>true,'message'=>'Staff list loaded.','staff'=>ad_service_attach_related($result['rows']),'pagination'=>['page'=>$page,'limit'=>$limit,'total'=>$total,'pages'=>(int)ceil($total/$limit)]];}
function ad_service_staff_get($staff_id){if($staff_id<1)return ['ok'=>false,'message'=>'A valid staff_id is required.'];$result=ad_repo_staff($staff_id);if(!$result['ok'])return $result;if(!$result['row'])return ['ok'=>false,'message'=>'Staff record not found.'];return ['ok'=>true,'message'=>'Staff record loaded.','staff'=>ad_service_attach_related([$result['row']])[0]];}
function ad_service_stats(){return ['ok'=>true,'message'=>'Staff statistics loaded.','stats'=>['total_staff'=>ad_repo_staff_count(['include_deleted'=>false])]];}
function ad_service_users($request){$rows=ad_repo_users(ad_clean_text($request['search']??''));return ['ok'=>true,'message'=>'Users loaded.','users'=>$rows];}
function ad_service_user_get($id){$row=ad_repo_user($id);return $row?['ok'=>true,'message'=>'User loaded.','user'=>$row]:['ok'=>false,'message'=>'User not found.'];}
function ad_service_user_edit($post){$id=ad_clean_int($post['user_id']??0);$username=ad_clean_text($post['username']??'');$role=ad_clean_int($post['role_id']??0);if($id<1||$username===''||$role<1)return ['ok'=>false,'message'=>'Username, role, and user ID are required.'];if(!ad_repo_update_user($id,['username'=>$username,'role_id'=>$role,'drole'=>ad_clean_int($post['drole']??0)]))return ['ok'=>false,'message'=>'Could not update user details.'];return ['ok'=>true,'message'=>'User details updated.'];}
function ad_service_user_create($post){$staff_id=ad_clean_int($post['staff_id']??0);$role_id=ad_clean_int($post['role_id']??0);$username=ad_clean_text($post['username']??'');$role=ad_repo_role($role_id);if($staff_id<1||$role_id<1||$username==='')return ['ok'=>false,'message'=>'Staff, username, and role are required.'];if(ad_repo_username_exists($username))return ['ok'=>false,'message'=>'Username already exists.'];$panel=(int)($role['role_access_panel']??0);$password=(string)($post['password']??'');$pin=(string)($post['pin']??'');if((in_array($panel,[1,3],true)&&$password==='')||(in_array($panel,[2,3],true)&&$pin===''))return ['ok'=>false,'message'=>'Credentials required by the selected role.'];$id=ad_repo_insert_user($staff_id,['username'=>$username,'password'=>in_array($panel,[1,3],true)?$password:'','pin'=>in_array($panel,[2,3],true)?$pin:'','role_id'=>$role_id,'drole'=>ad_clean_int($post['drole']??0),'sys_default'=>2,'work_status'=>2]);return $id?['ok'=>true,'message'=>'User created successfully.','user_id'=>$id]:['ok'=>false,'message'=>'Could not create user.'];}
function ad_service_user_credential($post,$column){$id=ad_clean_int($post['user_id']??0);$value=(string)($post['value']??'');$confirm=(string)($post['confirm']??'');if($id<1||$value===''||$value!==$confirm)return ['ok'=>false,'message'=>'The new credential is required and must match confirmation.'];if(!ad_repo_update_user_credential($id,$column,$value))return ['ok'=>false,'message'=>'Could not update user credential.'];return ['ok'=>true,'message'=>ucfirst($column).' changed successfully.'];}
function ad_service_user_target($post){$id=ad_clean_int($post['user_id']??0);$amount=(float)($post['max_sale']??-1);if($id<1||$amount<0)return ['ok'=>false,'message'=>'Enter a valid non-negative target.'];if(!ad_repo_update_user_target($id,$amount))return ['ok'=>false,'message'=>'Could not update target.'];return ['ok'=>true,'message'=>'Target updated successfully.'];}
function ad_service_user_permissions($post){$id=ad_clean_int($post['user_id']??0);$permissions=is_array($post['permissions']??null)?$post['permissions']:[];if($id<1)return ['ok'=>false,'message'=>'Invalid user.'];if(!ad_repo_update_permissions($id,$permissions))return ['ok'=>false,'message'=>'Could not save permissions.'];return ['ok'=>true,'message'=>'Permissions saved successfully.'];}
function ad_service_user_status($post,$status){$id=ad_clean_int($post['user_id']??0);if($id<1)return ['ok'=>false,'message'=>'Invalid user.'];if($status===1&&trim((string)($post['reason']??''))==='')return ['ok'=>false,'message'=>'A suspension reason is required.'];if(!ad_repo_user_status($id,$status))return ['ok'=>false,'message'=>'Could not update user status.'];if($status===1&&!ad_repo_user_discipline($id,ad_clean_text($post['reason']??''),(int)($_SESSION['user_id']??0)))return ['ok'=>false,'message'=>'User status changed, but the suspension record could not be saved.'];return ['ok'=>true,'message'=>$status===1?'User suspended successfully.':'User unsuspended successfully.'];}
function ad_service_user_permission_data($id){$user=ad_repo_user($id);if(!$user)return ['ok'=>false,'message'=>'User not found.'];$current=array_filter(array_map('intval',preg_split('/\s*,\s*/',(string)($user['permissions']??''))));return ['ok'=>true,'message'=>'Permissions loaded.','permissions'=>ad_repo_permission_items(),'selected'=>$current];}

function ad_service_relationships(){return ['ok'=>true,'message'=>'Relationships loaded.','relationships'=>ad_repo_relationships()];}
function ad_service_roles(){return ['ok'=>true,'message'=>'Roles loaded.','roles'=>ad_repo_roles()];}
function ad_service_role_list(){return ['ok'=>true,'message'=>'Detailed roles loaded.','roles'=>ad_repo_roles()];}
function ad_service_role_get($id){$row=ad_repo_role($id);return $row?['ok'=>true,'message'=>'Role loaded.','role'=>$row]:['ok'=>false,'message'=>'Role not found.'];}
function ad_service_role_save($post){$name=ad_clean_text($post['role_name']??'');$panel=ad_clean_int($post['role_access_panel']??0);if($name===''||!in_array($panel,[1,2,3],true))return ['ok'=>false,'message'=>'Role name and a valid access panel are required.'];$id=ad_repo_role_save(['role_name'=>$name,'role_description'=>ad_clean_text($post['role_description']??''),'role_access_panel'=>$panel,'access_dash'=>ad_clean_int($post['access_dash']??0)?1:0,'front_perm'=>trim((string)($post['front_perm']??''))],ad_clean_int($post['role_id']??0));return $id?['ok'=>true,'message'=>'Role saved successfully.','role_id'=>$id]:['ok'=>false,'message'=>'Could not save role.'];}

function ad_service_save_staff($post,$files,$user_id=0)
{
    global $connection;
    $post=is_array($post)?$post:[];$files=is_array($files)?$files:[];
    foreach(['staff_name','staff_phone','staff_residence','nok_name','nok_phone','nok_relationship'] as $required){if(trim((string)($post[$required]??''))==='')return ['ok'=>false,'message'=>'Missing required field: '.$required];}
    $staff=[
        'staff_name'=>ad_clean_text($post['staff_name']??''),'surname'=>ad_clean_text($post['surname']??''),'alias'=>ad_clean_text($post['alias']??''),'staff_nid'=>ad_clean_text($post['staff_nid']??''),'staff_email'=>ad_clean_text($post['staff_email']??''),'staff_address'=>ad_clean_text($post['staff_address']??''),'staff_phone'=>ad_clean_text($post['staff_phone']??''),'whatsphone'=>ad_clean_text($post['whatsphone']??''),'staff_nssf'=>ad_clean_text($post['staff_nssf']??''),'staff_nhif'=>ad_clean_text($post['staff_nhif']??''),'staff_kra_pin'=>ad_clean_text($post['staff_kra_pin']??''),'staff_residence'=>ad_clean_text($post['staff_residence']??''),'staff_del_status'=>2,'staff_user_status'=>0,'staff_hire_date'=>ad_clean_text($post['hire_date']??date('Y-m-d H:i:s')),'work_status'=>ad_clean_text($post['work_status']??'Active'),'salary_cycle'=>ad_clean_text($post['salary_cycle']??''),'salary_type'=>ad_clean_text($post['salary_type']??''),'basic_salary'=>ad_clean_text($post['basic_salary']??'')
    ];
    $nok=['nok_name'=>ad_clean_text($post['nok_name']??''),'nok_phone'=>ad_clean_text($post['nok_phone']??''),'nok_id_number'=>ad_clean_text($post['nok_id']??''),'nok_relationship'=>ad_clean_text($post['nok_relationship']??''),'nok_address'=>ad_clean_text($post['nok_address']??''),'nok_residence'=>ad_clean_text($post['nok_residence']??'')];
    $employment=['department_name'=>ad_clean_text($post['department_name']??''),'job_title'=>ad_clean_text($post['job_title']??''),'employment_type'=>ad_clean_text($post['employment_type']??''),'contract_type'=>ad_clean_text($post['contract_type']??''),'work_status'=>ad_clean_text($post['work_status']??'Active'),'start_date'=>ad_clean_text($post['start_date']??''),'hire_date'=>ad_clean_text($post['hire_date']??''),'probation_end_date'=>ad_clean_text($post['probation_end_date']??''),'contract_end_date'=>ad_clean_text($post['contract_end_date']??''),'supervisor_name'=>ad_clean_text($post['supervisor_name']??''),'notes'=>ad_clean_text($post['employment_notes']??'')];
    $make_user=!empty($post['make_user'])&&ad_clean_text($post['make_user'])!=='0';$user=[];
    if($make_user){$role_id=ad_clean_int($post['role_id']??0);$role=ad_repo_role($role_id);if(!$role)return ['ok'=>false,'message'=>'Select a valid user role.'];$panel=(int)($role['role_access_panel']??0);$username=ad_clean_text($post['username']??'');$password=(string)($post['user_password']??'');$password_confirm=(string)($post['user_password_confirm']??'');$pin=(string)($post['user_pin']??'');$pin_confirm=(string)($post['user_pin_confirm']??'');if($username===''||ad_repo_username_exists($username))return ['ok'=>false,'message'=>$username===''?'Username is required.':'Username already exists.'];if(in_array($panel,[1,3],true)&&($password===''||$password!==$password_confirm))return ['ok'=>false,'message'=>'Password is required and must match confirmation.'];if(in_array($panel,[2,3],true)&&($pin===''||$pin!==$pin_confirm))return ['ok'=>false,'message'=>'PIN is required and must match confirmation.'];$user=['username'=>$username,'password'=>in_array($panel,[1,3],true)?$password:'','pin'=>in_array($panel,[2,3],true)?$pin:'','role_id'=>$role_id,'drole'=>ad_clean_int($post['drole']??0),'sys_default'=>2,'work_status'=>2];}
    $moved=[];
    try { mysqli_begin_transaction($connection);$staff_id=ad_repo_insert_staff($staff);if($staff_id<1)throw new RuntimeException(ad_db_error($connection,'Could not create staff record.'));$user_id=0;if($make_user){$user_id=ad_repo_insert_user($staff_id,$user);if($user_id<1)throw new RuntimeException(ad_db_error($connection,'Could not create user account.'));}if(!ad_repo_insert_nok($staff_id,$nok))throw new RuntimeException(ad_db_error($connection,'Could not save next of kin.'));if($employment['department_name']!==''||$employment['job_title']!==''||$employment['employment_type']!==''){if(!ad_repo_insert_employment($staff_id,$employment))throw new RuntimeException(ad_db_error($connection,'Could not save employment details.'));}
        $uploads=[
            'staff_photo'=>['category'=>'staff','code'=>'STAFF_PHOTO','title'=>'Staff profile photo','column'=>'staff_photo'],
            'staff_nid_img'=>['category'=>'nid','code'=>'NATIONAL_ID','title'=>'National ID','column'=>'staff_nid_img'],
            'staff_cv'=>['category'=>'docs','code'=>'CV','title'=>'Curriculum vitae','column'=>'staff_cv'],
            'staff_conduct_img'=>['category'=>'docs','code'=>'CONDUCT','title'=>'Certificate of conduct','column'=>'staff_conduct_img'],
            'staff_kin_id_image'=>['category'=>'docs','code'=>'KIN_ID','title'=>'Next of kin ID','column'=>'staff_kin_id_image']
        ];
        foreach($uploads as $field=>$meta){$file=$files[$field]??null;if(!$file||($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)continue;if(($file['error']??0)!==UPLOAD_ERR_OK)throw new RuntimeException('Upload failed for '.$field.'.');$folder=dirname(__DIR__).'/docs/'.$meta['category'];if(!is_dir($folder)&&!mkdir($folder,0775,true))throw new RuntimeException('Could not create document folder.');$original=basename((string)$file['name']);$safe=preg_replace('/[^A-Za-z0-9._-]+/','_', $original);$stored=$staff_id.'_'.date('YmdHis').'_'.bin2hex(random_bytes(3)).'_'.$safe;$target=$folder.'/'.$stored;if(!move_uploaded_file($file['tmp_name'],$target))throw new RuntimeException('Could not store '.$field.'.');$moved[]=$target;$relative='ad/docs/'.$meta['category'].'/'.$stored;if(!ad_repo_update_staff_file($staff_id,$meta['column'],$relative)||!ad_repo_insert_document($staff_id,['doc_code'=>$meta['code'],'doc_title'=>$meta['title'],'file_name'=>$original,'file_path'=>$relative,'file_ext'=>pathinfo($original,PATHINFO_EXTENSION),'mime_type'=>$file['type']??'','file_size'=>(int)$file['size'],'is_current'=>1,'uploaded_by'=>(int)$user_id,'uploaded_at'=>date('Y-m-d H:i:s')]))throw new RuntimeException(ad_db_error($connection,'Could not save document record.'));}
        mysqli_commit($connection);return ['ok'=>true,'message'=>$make_user?'Staff and user saved successfully.':'Staff saved successfully.','staff_id'=>$staff_id,'user_id'=>$user_id];
    } catch(Throwable $error){mysqli_rollback($connection);foreach($moved as $path)if(is_file($path))@unlink($path);return ['ok'=>false,'message'=>$error->getMessage()];}
}
